exercise.solution:
def depasse_fenetre(ids, fenetre):
    if type(fenetre) is not int or fenetre<1:raise ValueError('fenêtre invalide')
    return len(ids)>fenetre

exercise.check:
assert not depasse_fenetre([1,2],2)
assert depasse_fenetre([1,2,3],2)
try:depasse_fenetre([1],0)
except ValueError:pass
else:raise AssertionError('fenêtre nulle')
